import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;
public class RealChordConfidenceInputsImageProbe extends RealOrnamentFactoryImageProbe {
 private final Object actualBook;
 public RealChordConfidenceInputsImageProbe(Book b,SortedSet<Integer> ids){super(b,ids);actualBook=b;}
 static Object readChord(Object sys,Object chord)throws Exception{Object sig=call(sys,"getSig");java.util.List<Object> members=new ArrayList<>(),containment=new ArrayList<>();for(Object head:(Collection<?>)call(chord,"getMembers"))members.add(map("id",id(head),"object",label(head),"kind",head.getClass().getSimpleName(),"bounds",bounds(head),"shape",call(head,"getShape"),"staff",id(field(head,"staff")),"raw_grade",field(head,"grade"),"contextual_grade",call(head,"getContextualGrade"),"best_grade",call(head,"getBestGrade"),"removed",call(head,"isRemoved")));for(Object edge:(Collection<?>)call(sig,"edgeSet"))if(edge.getClass().getSimpleName().equals("Containment")&&call(sig,"getEdgeSource",edge)==chord)containment.add(map("object",label(edge),"source_object",label(chord),"target_object",label(call(sig,"getEdgeTarget",edge)),"target_id",id(call(sig,"getEdgeTarget",edge)),"manual",call(edge,"isManual")));return map("id",id(chord),"object",label(chord),"bounds",bounds(chord),"raw_grade",field(chord,"grade"),"contextual_grade",call(chord,"getContextualGrade"),"raw_staff",id(field(chord,"staff")),"measure",owner(sys,call(chord,"getMeasure")),"voice",clock(chord,"voice"),"slot",clock(chord,"slot"),"time_offset",clock(chord,"timeOffset"),"members",members,"containment",containment);}
 public void process(){try{Object stub=((java.util.List<?>)call(actualBook,"getStubs")).get(0);java.util.List<Object> frames=new ArrayList<>();for(String stage:java.util.List.of("CHORDS","SYMBOLS")){call(stub,"reachStep",c("step.OmrStep").getField(stage).get(null),false);Object sheet=call(stub,"getSheet");for(Object sys:(java.util.List<?>)call(sheet,"getSystems")){java.util.List<Object> chords=new ArrayList<>();for(Object chord:(Collection<?>)call(call(sys,"getSig"),"inters",c("sig.inter.HeadChordInter")))chords.add(readChord(sys,chord));frames.add(map("stage","after_ordinary_"+stage,"system",id(sys),"head_chords",chords));}}Files.writeString(Path.of(System.getProperty("native.probe.output")),json(map("scope","Separate fresh unchanged DerWinter PNG: ordinary CHORDS cache construction boundary, then same stub ordinary SYMBOLS. Read actual HeadChord cached raw grade and actual member Head grade/bestGrade, geometry and Containment identities, plus Measure owners and clocks. Source values never initialize native recognition; no native output used.","frames",frames,"native_outputs_used",false))+"\n");}catch(Exception e){throw new RuntimeException(e);}}
}
